pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual.

    // 2. Lookahead Synergy (The "2-step" component):
    // If the next item fits perfectly into the current residual (post_residual), 
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        // Reward based on how well the next item fills the remaining space.
        score -= (100.0 - fit_gap).powf(1.5);
    }

    // 3. Prevent Fragmentation:
    // If post_residual is small but not zero, it creates "dead space" (e.g., 1-9).
    // Penalize small, unusable residuals that are smaller than the smallest likely item (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global Load Balancing:
    // If the current bin's residual is significantly above the mean, 
    // it's a "loose" bin. We prefer filling loose bins to consolidate space.
    if (bin_residual as f64) > mean_residual {
        score -= 20.0;
    }

    // 5. New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless we have no other choice (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works.
            score += 150.0;
        } else {
            // Base cost for opening a new bin.
            score += 50.0;
        }
    }

    // 6. Progression normalization:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (1..10) is the most dangerous range, (10..20) is secondary.
    if post_residual > 0 && post_residual < 10 {
        score += 85.0; 
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many bins are already open
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;
        // If we have very few bins open, we are more willing to open a new one to keep residuals high in existing ones
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Efficiency: If our mean residual is already high, we want to tighten current bins
    // This pushes the heuristic to prefer bins that result in smaller residuals when the average is loose
    score += (mean_residual * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // We prioritize perfect fits (post_residual == 0) and large residuals.
    if post_residual > 0 {
        score += (bin_capacity as f64) / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize placements that make it impossible
    // to fit the next item in this bin, unless it's a perfect fit for the current one.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that can accommodate the next item (Best-Fit Lookahead)
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current mean_residual 
    // is too low to support incoming items.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > (item_size as f64 * 1.2) {
            score += 100.0; // Heavily penalize opening new bins if existing capacity is sufficient
        } else {
            score -= 10.0; // Otherwise, incentivize spreading items out
        }
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression Scaling: As the stream nears completion, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}
